function uid() {
  return Math.random().toString(36).slice(2, 10) + Date.now().toString(36);
}

function useFonts() {
  useEffect(() => {
    const id = "jcb-fonts";
    if (document.getElementById(id)) return;
    const link = document.createElement("link");
    link.id = id;
    link.rel = "stylesheet";
    link.href = "https://fonts.googleapis.com/css2?family=Unbounded:wght@400;600;800&family=Cormorant+Garamond:ital,wght@0,300;0,400;0,500;1,400&family=Work+Sans:wght@400;500;600&family=Playfair+Display:wght@600;700&display=swap";
    document.head.appendChild(link);
  }, []);
}

// Guarda y lee los datos de la web en una única tabla de Supabase ("app_data"),
// compartida por todas las personas que entren a la página (tú y tus clientas).
async function storageGet(key) {
  try {
    const { data, error } = await supabase.from("app_data").select("value").eq("key", key).maybeSingle();
    if (error || !data) return null;
    return data.value;
  } catch {
    return null;
  }
}
async function storageSet(key, value) {
  try {
    const { error } = await supabase.from("app_data").upsert({ key, value, updated_at: new Date().toISOString() });
    if (error) console.error("storage set failed", error);
  } catch (e) {
    console.error("storage set failed", e);
  }
}

function timeToMinutes(t) { const [h, m] = t.split(":").map(Number); return h * 60 + m; }
function minutesToTime(m) { const h = Math.floor(m / 60).toString().padStart(2, "0"); const mm = (m % 60).toString().padStart(2, "0"); return `${h}:${mm}`; }
function formatDateHuman(dateStr) {
  const d = new Date(dateStr + "T00:00:00");
  return d.toLocaleDateString("es-ES", { weekday: "long", day: "numeric", month: "long" });
}
function monthKey(dateStr) { return dateStr.slice(0, 7); }
function monthLabel(key) { const [y, m] = key.split("-"); return `${MONTH_NAMES[parseInt(m, 10) - 1]} ${y}`; }

export default function App() {
  useFonts();
  const [view, setView] = useState("client");
  const [clientMode, setClientMode] = useState("menu");
  const [services, setServices] = useState(DEFAULT_SERVICES);
  const [availability, setAvailability] = useState(DEFAULT_AVAILABILITY);
  const [blockedDates, setBlockedDates] = useState([]);
  const [appointments, setAppointments] = useState([]);
  const [profile, setProfile] = useState(DEFAULT_PROFILE);
  const [reviews, setReviews] = useState([]);
  const [giftCards, setGiftCards] = useState([]);
  const [faqs, setFaqs] = useState(DEFAULT_FAQS.map((f) => ({ ...f, id: uid() })));
  const [loaded, setLoaded] = useState(false);
  const [adminAuthed, setAdminAuthed] = useState(false);

  const loadAll = useCallback(async () => {
    const [svc, avail, blocked, appts, prof, revs, gifts, faqList] = await Promise.all([
      storageGet("jcb:services", true),
      storageGet("jcb:availability", true),
      storageGet("jcb:blockedDates", true),
      storageGet("jcb:appointments", true),
      storageGet("jcb:profile", true),
      storageGet("jcb:reviews", true),
      storageGet("jcb:giftCards", true),
      storageGet("jcb:faqs", true),
    ]);
    if (svc) setServices(svc);
    if (avail) setAvailability(avail);
    if (blocked) setBlockedDates(blocked);
    if (appts) setAppointments(appts);
    if (prof) setProfile(prof);
    if (revs) setReviews(revs);
    if (gifts) setGiftCards(gifts);
    if (faqList) setFaqs(faqList);
    setLoaded(true);
  }, []);

  useEffect(() => { loadAll(); }, [loadAll]);

  const persistServices = async (next) => { setServices(next); await storageSet("jcb:services", next, true); };
  const persistAvailability = async (next) => { setAvailability(next); await storageSet("jcb:availability", next, true); };
  const persistBlockedDates = async (next) => { setBlockedDates(next); await storageSet("jcb:blockedDates", next, true); };
  const persistAppointments = async (next) => { setAppointments(next); await storageSet("jcb:appointments", next, true); };
  const persistProfile = async (next) => { setProfile(next); await storageSet("jcb:profile", next, true); };
  const persistReviews = async (next) => { setReviews(next); await storageSet("jcb:reviews", next, true); };
  const persistGiftCards = async (next) => { setGiftCards(next); await storageSet("jcb:giftCards", next, true); };
  const persistFaqs = async (next) => { setFaqs(next); await storageSet("jcb:faqs", next, true); };

  const appointmentDuration = (a) => {
    if (a.totalDuration) return a.totalDuration;
    const svc = services.find((s) => s.id === a.serviceId);
    return svc?.duration || 60;
  };

  const blockedRanges = (dateStr) =>
    appointments
      .filter((a) => a.date === dateStr && a.status !== "rechazada" && a.status !== "cancelada")
      .map((a) => {
        const start = timeToMinutes(a.time);
        return { start, end: start + appointmentDuration(a) };
      });

  const slotsForDate = (dateStr) => {
    if (!dateStr) return [];
    if (blockedDates.includes(dateStr)) return [];
    const conf = availability[dateStr];
    if (!conf || !conf.times) return [];
    const ranges = blockedRanges(dateStr);
    return conf.times
      .filter((t) => {
        const m = timeToMinutes(t);
        return !ranges.some((r) => m >= r.start && m < r.end);
      })
      .sort();
  };

  // Todas las horas configuradas ese día, con si están libres u ocupadas (para el calendario de la clienta)
  const allSlotsForDate = (dateStr) => {
    if (!dateStr) return [];
    if (blockedDates.includes(dateStr)) return [];
    const conf = availability[dateStr];
    if (!conf || !conf.times) return [];
    const ranges = blockedRanges(dateStr);
    return conf.times
      .map((t) => {
        const m = timeToMinutes(t);
        const available = !ranges.some((r) => m >= r.start && m < r.end);
        return { time: t, available };
      })
      .sort((a, b) => a.time.localeCompare(b.time));
  };

  const datesWithHours = Object.keys(availability).filter((d) => (availability[d]?.times || []).length > 0 && !blockedDates.includes(d));

  if (!loaded) {
    return (
      <div className="min-h-screen flex items-center justify-center" style={{ background: COLORS.bg }}>
        <p style={{ fontFamily: "'Work Sans', sans-serif", color: COLORS.muted }}>Cargando…</p>
      </div>
    );
  }

  return (
    <div className="min-h-screen" style={{ background: COLORS.bg, fontFamily: "'Work Sans', sans-serif", color: COLORS.ink }}>
      <style>{`
        .display-font { font-family: 'Unbounded', sans-serif; }
        .service-title { font-family: 'Playfair Display', serif; font-weight: 700; letter-spacing: 0.01em; }
        .hero-font { font-family: 'Cormorant Garamond', serif; font-weight: 400; }
        .jcb-input { width: 100%; padding: 10px 14px; border-radius: 12px; border: 1px solid ${COLORS.border}; background: #FFFFFF; color: ${COLORS.ink}; outline: none; }
        .jcb-input:focus { border-color: ${COLORS.accent}; }
        .jcb-mini-input { padding: 6px 10px; border-radius: 8px; border: 1px solid ${COLORS.border}; background: #FFF; color: ${COLORS.ink}; }
      `}</style>

      <TopBar view={view} setView={setView} clientMode={clientMode} setClientMode={setClientMode} />

      {view === "client" && (
        <>
          <ClientView
            profile={profile}
            services={services}
            reviews={reviews}
            faqs={faqs}
            slotsForDate={slotsForDate}
            allSlotsForDate={allSlotsForDate}
            datesWithHours={datesWithHours}
            mode={clientMode}
            setMode={setClientMode}
            onSubmit={async (appt) => {
              const next = [...appointments, { ...appt, id: uid(), status: "pendiente", createdAt: new Date().toISOString() }];
              await persistAppointments(next);
            }}
            onGiftCardRequest={async (gift) => {
              const next = [...giftCards, { ...gift, id: uid(), status: "pendiente", createdAt: new Date().toISOString() }];
              await persistGiftCards(next);
            }}
          />
          <SiteFooter profile={profile} setMode={setClientMode} />
        </>
      )}

      {view === "admin" && !adminAuthed && <AdminGate onAuth={() => setAdminAuthed(true)} />}

      {view === "admin" && adminAuthed && (
        <AdminView
          services={services} setServices={persistServices}
          availability={availability} setAvailability={persistAvailability}
          blockedDates={blockedDates} setBlockedDates={persistBlockedDates}
          appointments={appointments} setAppointments={persistAppointments}
          profile={profile} setProfile={persistProfile}
          reviews={reviews} setReviews={persistReviews}
          giftCards={giftCards} setGiftCards={persistGiftCards}
          faqs={faqs} setFaqs={persistFaqs}
        />
      )}
    </div>
  );
}

