function MiniFaqPreview({ faqs }) {
  const [open, setOpen] = useState(null);
  return (
    <div className="space-y-2">
      {faqs.map((item, i) => (
        <div key={item.id || i} className="rounded-xl overflow-hidden" style={{ background: COLORS.card, border: `1px solid ${COLORS.border}` }}>
          <button onClick={() => setOpen(open === i ? null : i)} className="w-full flex items-center justify-between px-4 py-3 text-left text-sm font-medium" style={{ color: COLORS.ink }}>
            {item.q}
            <ChevronDown size={16} color={COLORS.muted} style={{ transform: open === i ? "rotate(180deg)" : "none", transition: "transform 0.15s" }} />
          </button>
          {open === i && <p className="px-4 pb-4 text-sm" style={{ color: COLORS.muted }}>{item.a}</p>}
        </div>
      ))}
    </div>
  );
}

function ClientCalendar({ selectedDate, onSelectDate, datesWithHours }) {
  const todayStr = new Date().toISOString().slice(0, 10);
  const [monthCursor, setMonthCursor] = useState(() => { const d = new Date(); d.setDate(1); return d; });
  const availableSet = new Set(datesWithHours || []);

  const year = monthCursor.getFullYear();
  const month = monthCursor.getMonth();
  const firstOfMonth = new Date(year, month, 1);
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const startOffset = (firstOfMonth.getDay() + 6) % 7;

  const cells = [];
  for (let i = 0; i < startOffset; i++) cells.push(null);
  for (let d = 1; d <= daysInMonth; d++) cells.push(d);

  const dateStrFor = (d) => `${year}-${String(month + 1).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
  const changeMonth = (delta) => setMonthCursor(new Date(year, month + delta, 1));

  return (
    <div className="rounded-2xl p-4" style={{ background: COLORS.card, border: `1px solid ${COLORS.border}` }}>
      <div className="flex items-center justify-between mb-3">
        <button type="button" onClick={() => changeMonth(-1)} className="w-7 h-7 rounded-full flex items-center justify-center" style={{ background: COLORS.soft, color: COLORS.accentDark }}>‹</button>
        <p className="service-title text-sm capitalize" style={{ color: COLORS.ink }}>{MONTH_LABELS[month]} {year}</p>
        <button type="button" onClick={() => changeMonth(1)} className="w-7 h-7 rounded-full flex items-center justify-center" style={{ background: COLORS.soft, color: COLORS.accentDark }}>›</button>
      </div>
      <div className="grid grid-cols-7 gap-1 mb-1">
        {WEEKDAY_LABELS.map((w) => <div key={w} className="text-center text-xs" style={{ color: COLORS.muted }}>{w}</div>)}
      </div>
      <div className="grid grid-cols-7 gap-1">
        {cells.map((d, i) => {
          if (!d) return <div key={`e-${i}`} />;
          const dateStr = dateStrFor(d);
          const hasHours = availableSet.has(dateStr);
          const isPast = dateStr < todayStr;
          const selectable = hasHours && !isPast;
          const isSelected = dateStr === selectedDate;
          return (
            <button key={dateStr} type="button" disabled={!selectable} onClick={() => onSelectDate(dateStr)}
              className="aspect-square rounded-xl flex flex-col items-center justify-center"
              style={{
                background: isSelected ? COLORS.ink : selectable ? COLORS.soft : "transparent",
                opacity: selectable ? 1 : 0.35,
                cursor: selectable ? "pointer" : "default",
              }}>
              <span className="text-sm" style={{ color: isSelected ? "#FFF" : COLORS.ink }}>{d}</span>
              {hasHours && !isSelected && <span className="w-1.5 h-1.5 rounded-full mt-0.5" style={{ background: COLORS.accent }} />}
            </button>
          );
        })}
      </div>
    </div>
  );
}

function BackButton({ onClick }) {
  return (
    <button onClick={onClick} className="flex items-center gap-1 text-xs mb-6 opacity-70 hover:opacity-100" style={{ color: COLORS.muted }}>
      <ArrowLeft size={13} /> Volver
    </button>
  );
}

function BookingFlow({ profile, services, slotsForDate, allSlotsForDate, datesWithHours, onSubmit }) {
  const [selectedService, setSelectedService] = useState(null);
  const [extraIds, setExtraIds] = useState([]);
  const [form, setForm] = useState({ name: "", phone: "", email: "", date: "", time: "" });
  const [sent, setSent] = useState(false);
  const slots = slotsForDate(form.date);

  const extraServices = services.filter((s) => extraIds.includes(s.id));
  const totalPrice = (selectedService?.price || 0) + extraServices.reduce((sum, s) => sum + s.price, 0);
  const totalDuration = (selectedService?.duration || 0) + extraServices.reduce((sum, s) => sum + s.duration, 0);

  const toggleExtra = (id) => setExtraIds((prev) => prev.includes(id) ? prev.filter((x) => x !== id) : [...prev, id]);

  const submit = (e) => {
    e.preventDefault();
    if (!selectedService || !form.name || !form.email || !form.date || !form.time) return;
    onSubmit({
      ...form,
      serviceId: selectedService.id,
      serviceName: extraServices.length ? `${selectedService.name} + ${extraServices.map((s) => s.name).join(" + ")}` : selectedService.name,
      totalPrice,
      totalDuration,
    });
    setSent(true);
  };

  if (sent) {
    return (
      <div className="text-center py-10">
        <div className="w-14 h-14 rounded-full flex items-center justify-center mx-auto mb-5" style={{ background: COLORS.soft }}>
          <Check size={26} color={COLORS.accentSoft} />
        </div>
        <h2 className="display-font text-xl mb-3" style={{ color: COLORS.ink }}>Solicitud enviada</h2>
        <p style={{ color: COLORS.muted }}>
          Tu cita para el {formatDateHuman(form.date)} a las {form.time} está en revisión. Te avisaré en cuanto quede confirmada.
        </p>
        <button
          onClick={() => { setSent(false); setSelectedService(null); setExtraIds([]); setForm({ name: "", phone: "", email: "", date: "", time: "" }); }}
          className="mt-8 text-sm underline" style={{ color: COLORS.accentSoft }}
        >
          Reservar otra cita
        </button>
      </div>
    );
  }

  return (
    <div>
      <h2 className="display-font text-xl md:text-2xl mb-2" style={{ color: COLORS.ink }}>Reserva tu cita</h2>
      <p className="mb-1" style={{ color: COLORS.muted }}>Elige tu servicio, la fecha y la hora que mejor te venga.</p>
      <p className="mb-8 text-xs italic" style={{ color: COLORS.muted }}>Los precios son de partida para diseños sencillos; el precio final puede variar según el diseño elegido.</p>

      {!selectedService && (
        <div className="mb-8">
          {SERVICE_CATEGORIES.map((cat) => {
            const items = services.filter((s) => (s.category || "Manicura").trim() === cat);
            if (items.length === 0) return null;
            return (
              <div key={cat} className="mb-8">
                <div className="flex items-center gap-3 mb-4"><h3 className="display-font text-lg" style={{ color: COLORS.ink }}>{cat}</h3><div className="flex-1 h-px" style={{ background: COLORS.border }} /></div>
                <div className="space-y-5">
                  {items.map((s) => (
                    <div key={s.id} className="rounded-2xl overflow-hidden" style={{ background: COLORS.card, border: `1px solid ${COLORS.border}` }}>
                      {s.photo ? (
                        <img src={s.photo} alt={s.name} className="w-full h-48 object-cover" />
                      ) : (
                        <div className="w-full h-48 flex items-center justify-center" style={{ background: COLORS.soft }}>
                          <Sparkles size={22} color={COLORS.accentSoft} />
                        </div>
                      )}
                      <div className="p-5">
                        <h3 className="service-title text-base mb-2" style={{ color: COLORS.ink }}>{s.name}</h3>
                        <p className="text-sm" style={{ color: COLORS.muted }}>{s.description}</p>
                        <div className="flex items-center gap-4 mt-4 text-sm" style={{ color: COLORS.ink }}>
                          <span className="flex items-center gap-1"><Clock size={14} color={COLORS.muted} /> {formatDuration(s.duration)}</span>
                          <span style={{ color: COLORS.accentSoft, fontWeight: 600 }}>Desde {s.price} €</span>
                        </div>
                        <button onClick={() => setSelectedService(s)} className="mt-4 text-sm font-medium flex items-center gap-1" style={{ color: COLORS.accentSoft }}>
                          Reservar este servicio →
                        </button>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            );
          })}
        </div>
      )}

      {selectedService && (
        <div className="rounded-2xl overflow-hidden mb-8" style={{ background: COLORS.card, border: `1px solid ${COLORS.border}` }}>
          <div className="p-4 flex items-center gap-4">
            {selectedService.photo && <img src={selectedService.photo} alt={selectedService.name} className="w-16 h-16 object-cover rounded-lg flex-shrink-0" />}
            <div className="flex-1">
              <p className="service-title text-sm" style={{ color: COLORS.ink }}>{selectedService.name}</p>
              <p className="text-xs" style={{ color: COLORS.accentSoft }}>Desde {selectedService.price} € · {formatDuration(selectedService.duration)}</p>
            </div>
            <button onClick={() => { setSelectedService(null); setExtraIds([]); }} className="text-xs underline flex-shrink-0" style={{ color: COLORS.muted }}>Cambiar</button>
          </div>
        </div>
      )}

      {selectedService && services.length > 1 && (
        <div className="mb-8">
          <p className="text-sm font-medium mb-1" style={{ color: COLORS.ink }}>¿Quieres añadir algo más a tu cita?</p>
          <p className="text-xs mb-3" style={{ color: COLORS.muted }}>Por ejemplo, una pedicura junto con tu manicura.</p>
          <div className="space-y-2">
            {services.filter((s) => s.id !== selectedService.id).map((s) => (
              <label key={s.id} className="flex items-center gap-3 p-3 rounded-xl cursor-pointer" style={{ background: COLORS.card, border: `1px solid ${extraIds.includes(s.id) ? COLORS.accentSoft : COLORS.border}` }}>
                <input type="checkbox" checked={extraIds.includes(s.id)} onChange={() => toggleExtra(s.id)} className="flex-shrink-0" />
                <div className="flex-1">
                  <span className="service-title text-sm">{s.name}</span>
                  <span className="text-xs block" style={{ color: COLORS.muted }}>+{s.price} € · +{formatDuration(s.duration)}</span>
                </div>
              </label>
            ))}
          </div>
          {extraIds.length > 0 && (
            <p className="text-sm mt-3" style={{ color: COLORS.ink }}>
              Total: <span style={{ color: COLORS.accentSoft, fontWeight: 600 }}>{totalPrice} €</span> · {formatDuration(totalDuration)} aprox.
            </p>
          )}
        </div>
      )}

      {selectedService && (
        <form onSubmit={submit} className="space-y-4">
          <div className="grid md:grid-cols-2 gap-4">
            <Field label="Tu nombre"><input required value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} className="jcb-input" /></Field>
            <Field label="Teléfono"><input value={form.phone} onChange={(e) => setForm({ ...form, phone: e.target.value })} className="jcb-input" /></Field>
          </div>
          <Field label="Correo electrónico"><input required type="email" value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })} className="jcb-input" /></Field>

          <div>
            <span className="text-xs uppercase tracking-wide mb-2 block" style={{ color: COLORS.muted }}>Elige el día</span>
            <ClientCalendar
              selectedDate={form.date}
              onSelectDate={(d) => setForm({ ...form, date: d, time: "" })}
              datesWithHours={datesWithHours}
            />
            {profile?.monthlyPhrase && (
              <p className="hero-font italic text-lg mt-4 text-center" style={{ color: COLORS.accentSoft }}>"{profile.monthlyPhrase}"</p>
            )}
          </div>

          {form.date && (
            <div>
              <span className="text-xs uppercase tracking-wide mb-2 block" style={{ color: COLORS.muted }}>Horas de {formatDateHuman(form.date)}</span>
              {allSlotsForDate(form.date).length === 0 ? (
                <p className="text-sm italic" style={{ color: COLORS.muted }}>No hay horas puestas para este día.</p>
              ) : (
                <div className="flex flex-wrap gap-2">
                  {allSlotsForDate(form.date).map(({ time, available }) => (
                    <button key={time} type="button" disabled={!available} onClick={() => setForm({ ...form, time })}
                      className="px-4 py-2 rounded-full text-sm"
                      style={{
                        background: form.time === time ? COLORS.ink : available ? COLORS.card : "transparent",
                        color: form.time === time ? "#FFF" : available ? COLORS.ink : COLORS.muted,
                        border: `1px solid ${available ? COLORS.border : COLORS.border}`,
                        opacity: available ? 1 : 0.5,
                        textDecoration: available ? "none" : "line-through",
                        cursor: available ? "pointer" : "not-allowed",
                      }}>
                      {time}{!available && <span className="ml-1 text-xs">· ocupado</span>}
                    </button>
                  ))}
                </div>
              )}
            </div>
          )}

          <button type="submit" disabled={!form.time} className="w-full py-3 rounded-full display-font text-sm mt-4 transition" style={{ background: COLORS.accent, color: "#FFF", opacity: form.time ? 1 : 0.5 }}>
            Solicitar cita
          </button>
        </form>
      )}
    </div>
  );
}

function formatDuration(minutes) {
  if (!minutes) return "";
  if (minutes % 60 === 0) return `${minutes / 60} h`;
  if (minutes > 60) return `${Math.floor(minutes / 60)} h ${minutes % 60} min`;
  return `${minutes} min`;
}

function GiftCardForm({ onSubmit }) {
  const AMOUNTS = [20, 30, 40, 60];
  const [form, setForm] = useState({ amount: 30, buyerName: "", buyerEmail: "", recipientName: "", message: "" });
  const [sent, setSent] = useState(false);

  const submit = (e) => {
    e.preventDefault();
    if (!form.buyerName || !form.buyerEmail || !form.recipientName) return;
    onSubmit(form);
    setSent(true);
  };

  if (sent) {
    return (
      <div className="text-center py-10">
        <div className="w-14 h-14 rounded-full flex items-center justify-center mx-auto mb-5" style={{ background: COLORS.soft }}>
          <Check size={26} color={COLORS.accentSoft} />
        </div>
        <h2 className="display-font text-xl mb-3" style={{ color: COLORS.ink }}>¡Solicitud recibida!</h2>
        <p style={{ color: COLORS.muted }}>Me pondré en contacto contigo para confirmar el pago y hacerte llegar la tarjeta de regalo.</p>
      </div>
    );
  }

  return (
    <div>
      <h2 className="display-font text-xl md:text-2xl mb-2" style={{ color: COLORS.ink }}>Tarjeta de regalo</h2>
      <p className="mb-8" style={{ color: COLORS.muted }}>Regala una experiencia de belleza. Elige el importe y te contacto para confirmar el pago y la entrega.</p>

      <form onSubmit={submit} className="space-y-4">
        <div>
          <span className="text-xs uppercase tracking-wide mb-2 block" style={{ color: COLORS.muted }}>Importe</span>
          <div className="flex flex-wrap gap-2">
            {AMOUNTS.map((a) => (
              <button type="button" key={a} onClick={() => setForm({ ...form, amount: a })} className="px-4 py-2 rounded-full text-sm"
                style={{ background: form.amount === a ? COLORS.ink : COLORS.card, color: form.amount === a ? "#FFF" : COLORS.ink, border: `1px solid ${COLORS.border}` }}>
                {a}€
              </button>
            ))}
          </div>
        </div>
        <div className="grid md:grid-cols-2 gap-4">
          <Field label="Tu nombre"><input required value={form.buyerName} onChange={(e) => setForm({ ...form, buyerName: e.target.value })} className="jcb-input" /></Field>
          <Field label="Tu correo"><input required type="email" value={form.buyerEmail} onChange={(e) => setForm({ ...form, buyerEmail: e.target.value })} className="jcb-input" /></Field>
        </div>
        <Field label="Nombre de quien lo recibe"><input required value={form.recipientName} onChange={(e) => setForm({ ...form, recipientName: e.target.value })} className="jcb-input" /></Field>
        <Field label="Mensaje (opcional)"><textarea value={form.message} onChange={(e) => setForm({ ...form, message: e.target.value })} className="jcb-input" rows={3} /></Field>
        <button type="submit" className="w-full py-3 rounded-full display-font text-sm mt-4 transition" style={{ background: COLORS.accent, color: "#FFF" }}>
          Solicitar tarjeta de regalo
        </button>
      </form>
    </div>
  );
}

